1	/**
2	 * 多签钱包策略引擎。
3	 *
4	 * 在阈值策略、签名收集、重放防护、FIFO 执行队列与策略变更任务之上，新增“任务取消”：
5	 * 当前所有者以阈值签名（safe-wallet/cancel/v1 域，绑定钱包标识、目标任务 digest、nonce、
6	 * 截止时间）撤销尚未执行的 queued 任务；目标任务进入 cancelled 终态（保留原 payload/
7	 * digest/nonce，记录取消时间与摘要），不执行其效果、不改变策略、只消费本次 nonce。
8	 */
9	
10	import {
11	  type Address,
12	  ZERO_ADDRESS,
13	  isZeroAddress,
14	  normalizeAddress,
15	  recoverAddress,
16	} from './crypto.ts';
17	import {
18	  hashCancellation,
19	  hashPolicyChange,
20	  hashTransaction,
21	  type PolicyChangeRequest,
22	  type TransactionRequest,
23	} from './encoding.ts';
24	import {
25	  InvalidCancellation,
26	  InvalidPolicyChange,
27	  InvalidTransaction,
28	  NonceAlreadyUsedError,
29	  RequestExpired,
30	  PolicyConflict,
31	  InvalidQueueStateError,
32	  TaskCancellationConflict,
33	  TaskNotFoundError,
34	} from './errors.ts';
35	import { ExecutionQueue, type QueueTask } from './queue.ts';
36	
37	// ---------- 任务载荷 ----------
38	
39	export type WalletTaskPayload =
40	  | {
41	      kind: 'transaction';
42	      deadline: bigint;
43	      to: Address;
44	      value: bigint;
45	      data: Uint8Array;
46	    }
47	  | {
48	      kind: 'policy-change';
49	      deadline: bigint;
50	      /** 提交时绑定的策略版本；执行时必须仍等于当前版本 */
51	      version: bigint;
52	      newOwners: Address[];
53	      newConfirmations: bigint;
54	    };
55	
56	export type WalletTask = QueueTask<WalletTaskPayload>;
57	
58	export interface PolicyState {
59	  owners: Address[];
60	  confirmations: bigint;
61	  version: bigint;
62	}
63	
64	export interface WalletOptions {
65	  id: string;
66	  owners: Address[];
67	  confirmations: bigint | number;
68	  /** 注入时钟，返回 Unix 秒；默认取系统时间 */
69	  now?: () => bigint;
70	}
71	
72	export interface TransactionSubmission {
73	  nonce: bigint | number;
74	  deadline: bigint | number;
75	  to: string;
76	  value: bigint | number;
77	  data?: Uint8Array;
78	}
79	
80	export interface PolicyChangeSubmission {
81	  version: bigint | number;
82	  nonce: bigint | number;
83	  deadline: bigint | number;
84	  newOwners: string[];
85	  newConfirmations: bigint | number;
86	}
87	
88	export interface CancellationSubmission {
89	  /** 目标任务 id（队列快照中的任务标识） */
90	  taskId: string;
91	  nonce: bigint | number;
92	  deadline: bigint | number;
93	}
94	
95	function isNonNegativeInteger(n: bigint, maxBits = 256): boolean {
96	  return n >= 0n && n < 2n ** BigInt(maxBits);
97	}
98	
99	/** 安全标量转换：非法输入（undefined / 字符串等）归一为指定的 Invalid* 错误 */
100	function toBigInt(value: unknown, Invalid: new (msg: string) => Error, field: string): bigint {
101	  if (typeof value === 'bigint') return value;
102	  if (typeof value === 'number' && Number.isSafeInteger(value)) return BigInt(value);
103	  if (typeof value === 'string' && /^\d+$/.test(value.trim())) return BigInt(value.trim());
104	  throw new Invalid(`field "${field}" must be a non-negative integer`);
105	}
106	
107	export class MultiSigWallet {
108	  readonly id: string;
109	  private readonly now: () => bigint;
110	
111	  private owners: Address[];
112	  private readonly ownerSet: Set<Address>;
113	  private confirmations: bigint;
114	  private version: bigint;
115	
116	  /** 下一个期望 nonce（严格递增，顺序提交） */
117	  private nextNonce = 0n;
118	  /** 已消费 nonce（入队即消费；失败终态也不释放） */
119	  private readonly usedNonces = new Set<bigint>();
120	
121	  readonly queue: ExecutionQueue<WalletTaskPayload>;
122	
123	  constructor(opts: WalletOptions) {
124	    const owners = normalizeOwnerList(opts.owners);
125	    const confirmations = BigInt(opts.confirmations);
126	    if (confirmations <= 0n || confirmations > BigInt(owners.length)) {
127	      throw new InvalidPolicyChange(
128	        `initial confirmations must be within 1..owners (${owners.length}), got ${confirmations}`,
129	      );
130	    }
131	    this.id = opts.id;
132	    this.now = opts.now ?? (() => BigInt(Math.floor(Date.now() / 1000)));
133	    this.owners = owners;
134	    this.ownerSet = new Set(owners);
135	    this.confirmations = confirmations;
136	    this.version = 1n;
137	    this.queue = new ExecutionQueue((task) => this.applyTask(task));
138	  }
139	
140	  // ---------- 只读状态 ----------
141	
142	  get policy(): PolicyState {
143	    return { owners: [...this.owners], confirmations: this.confirmations, version: this.version };
144	  }
145	
146	  get policyVersion(): bigint {
147	    return this.version;
148	  }
149	
150	  get currentOwners(): Address[] {
151	    return [...this.owners];
152	  }
153	
154	  get requiredConfirmations(): bigint {
155	    return this.confirmations;
156	  }
157	
158	  get expectedNonce(): bigint {
159	    return this.nextNonce;
160	  }
161	
162	  isOwner(address: string): boolean {
163	    const a = normalizeAddress(address);
164	    return a !== null && this.ownerSet.has(a);
165	  }
166	
167	  isNonceUsed(nonce: bigint | number): boolean {
168	    return this.usedNonces.has(BigInt(nonce));
169	  }
170	
171	  get tasks(): readonly WalletTask[] {
172	    return this.queue.listTasks();
173	  }
174	
175	  // ---------- 普通交易提交（行为与既有流程一致，载荷不含策略版本） ----------
176	
177	  submitTransaction(sub: TransactionSubmission, signatures: readonly Uint8Array[]): WalletTask {
178	    // 原始值透传，由 submit 统一做安全转换，避免在入口抛出原生 TypeError
179	    return this.submit(
180	      'transaction',
181	      {
182	        nonce: sub.nonce,
183	        deadline: sub.deadline,
184	        to: sub.to,
185	        value: sub.value,
186	        data: sub.data ?? new Uint8Array(),
187	      },
188	      signatures,
189	    );
190	  }
191	
192	  // ---------- 策略变更提交 ----------
193	
194	  proposePolicyChange(sub: PolicyChangeSubmission, signatures: readonly Uint8Array[]): WalletTask {
195	    return this.submit(
196	      'policy-change',
197	      {
198	        version: sub.version,
199	        nonce: sub.nonce,
200	        deadline: sub.deadline,
201	        newOwners: sub.newOwners,
202	        newConfirmations: sub.newConfirmations,
203	      },
204	      signatures,
205	    );
206	  }
207	
208	  // ---------- 任务取消 ----------
209	
210	  /**
211	   * 取消一个尚未执行的 queued 任务。
212	   *
213	   * 取消摘要使用 safe-wallet/cancel/v1 域标签，绑定钱包标识、目标任务 digest、nonce 与
214	   * 截止时间：签名无法改绑其他任务、其他钱包或其他时间窗口。
215	   *
216	   * 校验顺序（任一失败都不改变任务、不消费 nonce、不改变策略）：
217	   *   1) 字段非法 → InvalidCancellation
218	   *   2) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
219	   *   3) deadline 早于当前时间 → RequestExpired
220	   *   4) nonce 顺序（须等于 expectedNonce）→ InvalidCancellation
221	   *   5) 目标不存在 → TaskNotFoundError；目标已终态 → TaskCancellationConflict
222	   *   6) 阈值签名（当前所有者、去重后达到当前确认数）→ InvalidCancellation
223	   *
224	   * 成功时目标任务由 queued 进入 cancelled 终态并返回：保留原 payload/digest/nonce，
225	   * 记录取消时间与取消摘要；不执行目标效果，不改变 owners/确认数/策略版本，
226	   * 只消费本次 nonce 并推进 expectedNonce。取消不要求任务在队首，也不调整队列顺序。
227	   */
228	  cancelTask(
229	    taskId: string,
230	    nonce: bigint | number,
231	    deadline: bigint | number,
232	    signatures: readonly Uint8Array[],
233	  ): WalletTask;
234	  cancelTask(sub: CancellationSubmission, signatures: readonly Uint8Array[]): WalletTask;
235	  cancelTask(
236	    a: string | CancellationSubmission,
237	    b: readonly Uint8Array[] | bigint | number,
238	    c?: bigint | number,
239	    d?: readonly Uint8Array[],
240	  ): WalletTask {
241	    const sub: CancellationSubmission =
242	      typeof a === 'string' || a === undefined || a === null
243	        ? { taskId: a as string, nonce: b as bigint | number, deadline: c as bigint | number }
244	        : a;
245	    const signatures: readonly Uint8Array[] =
246	      (typeof a === 'string' || a === undefined || a === null ? d : (b as readonly Uint8Array[])) ??
247	      ([] as readonly Uint8Array[]);
248	
249	    // (1) 字段安全转换（畸形输入只抛 InvalidCancellation）
250	    const nonce = toBigInt(sub.nonce, InvalidCancellation, 'nonce');
251	    if (!isNonNegativeInteger(nonce)) {
252	      throw new InvalidCancellation('nonce must be a non-negative integer');
253	    }
254	    // (2) nonce 复用优先于过期判定
255	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
256	
257	    const deadline = toBigInt(sub.deadline, InvalidCancellation, 'deadline');
258	    if (!isNonNegativeInteger(deadline)) throw new InvalidCancellation('deadline out of range');
259	    // (3) 截止时间
260	    if (deadline < this.now()) {
261	      throw new RequestExpired(`request deadline ${deadline} already passed`);
262	    }
263	    // (4) nonce 顺序：取消与提交共用同一严格递增序列
264	    if (nonce !== this.nextNonce) {
265	      throw new InvalidCancellation(`expected nonce ${this.nextNonce}, got ${nonce}`);
266	    }
267	
268	    // (5) 目标任务状态
269	    const taskId = sub.taskId;
270	    if (typeof taskId !== 'string' || taskId.length === 0) {
271	      throw new InvalidCancellation('taskId must be a non-empty string');
272	    }
273	    const target = this.queue.getTask(taskId);
274	    if (target === null) throw new TaskNotFoundError(`task not found: ${taskId}`);
275	    if (target.status !== 'queued') {
276	      throw new TaskCancellationConflict(`task ${taskId} is already ${target.status}`);
277	    }
278	
279	    // (6) 阈值签名：摘要绑定钱包标识、目标任务 digest、nonce、deadline
280	    const digest = hashCancellation({
281	      walletId: this.id,
282	      taskDigest: target.digest,
283	      nonce,
284	      deadline,
285	    });
286	    this.verifyThresholdSignatures(digest, signatures, InvalidCancellation);
287	
288	    // 原子生效：目标任务进入 cancelled 终态 + 消费 nonce；策略与队列顺序不变
289	    const cancelled = this.queue.cancel(taskId, this.now(), digest.toString('hex'));
290	    this.usedNonces.add(nonce);
291	    this.nextNonce = nonce + 1n;
292	    return cancelled;
293	  }
294	
295	  // ---------- 执行 ----------
296	
297	  executeTask(taskId: string): WalletTask {
298	    return this.queue.execute(taskId, this.now());
299	  }
300	
301	  executeNext(): WalletTask | null {
302	    return this.queue.executeNext(this.now());
303	  }
304	
305	  getTask(taskId: string): WalletTask | null {
306	    return this.queue.getTask(taskId);
307	  }
308	
309	  // ============================================================
310	  // 内部实现
311	  // ============================================================
312	
313	  /**
314	   * 统一提交入口。raw 接收未经转换的原始标量（bigint/number/string），
315	   * 所有转换与字段合法性判定都在这里完成，保证只能抛出约定错误类型。
316	   */
317	  private submit(
318	    kind: WalletTaskPayload['kind'],
319	    raw: Record<string, unknown>,
320	    signatures: readonly Uint8Array[],
321	  ): WalletTask {
322	    const Invalid = kind === 'policy-change' ? InvalidPolicyChange : InvalidTransaction;
323	
324	    // 校验优先级（任一失败都不建任务、不消费 nonce、不改策略）：
325	    //   1) nonce 复用 → 既有重放防护的公开异常（旧请求重放即使已过期也仍报复用）
326	    //   2) 截止时间早于当前时间 → RequestExpired
327	    //   3) 字段 / 版本 / nonce 顺序 / 签名 → 对应 Invalid*
328	    const nonce = toBigInt(raw.nonce, Invalid, 'nonce');
329	    if (!isNonNegativeInteger(nonce)) throw new Invalid('nonce must be a non-negative integer');
330	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
331	
332	    const deadline = toBigInt(raw.deadline, Invalid, 'deadline');
333	    if (!isNonNegativeInteger(deadline)) throw new Invalid('deadline out of range');
334	    if (deadline < this.now()) {
335	      throw new RequestExpired(`request deadline ${deadline} already passed`);
336	    }
337	    if (nonce !== this.nextNonce) throw new Invalid(`expected nonce ${this.nextNonce}, got ${nonce}`);
338	
339	    // (3) 字段校验 + 规范化
340	    let payload: WalletTaskPayload;
341	    let digest: Buffer;
342	    if (kind === 'transaction') {
343	      const to = normalizeAddress(raw.to as string);
344	      if (to === null || isZeroAddress(to)) throw new Invalid('invalid or zero recipient address');
345	      const value = toBigInt(raw.value, Invalid, 'value');
346	      if (!isNonNegativeInteger(value)) throw new Invalid('value out of range');
347	      const dataField = raw.data;
348	      if (
349	        dataField !== undefined &&
350	        !(dataField instanceof Uint8Array) &&
351	        !ArrayBuffer.isView(dataField)
352	      ) {
353	        throw new Invalid('data must be a byte array');
354	      }
355	      const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
356	      const req: TransactionRequest = {
357	        walletId: this.id,
358	        nonce,
359	        deadline,
360	        to,
361	        value,
362	        data,
363	      };
364	      digest = hashTransaction(req);
365	      payload = { kind: 'transaction', deadline, to, value, data };
366	    } else {
367	      const version = toBigInt(raw.version, InvalidPolicyChange, 'version');
368	      // (3a) 版本必须绑定当前版本（提交时不匹配 → InvalidPolicyChange；执行时漂移 → PolicyConflict）
369	      if (version !== this.version) {
370	        throw new InvalidPolicyChange(
371	          `policy version mismatch: bound ${version}, current ${this.version}`,
372	        );
373	      }
374	      // (3b) 以当前版本为基准验证新策略
375	      const newOwners = normalizeOwnerList(raw.newOwners as string[], InvalidPolicyChange);
376	      const newConfirmations = toBigInt(raw.newConfirmations, InvalidPolicyChange, 'newConfirmations');
377	      if (newConfirmations <= 0n || newConfirmations > BigInt(newOwners.length)) {
378	        throw new InvalidPolicyChange(
379	          `new confirmations must be within 1..new owners (${newOwners.length}), got ${newConfirmations}`,
380	        );
381	      }
382	      const req: PolicyChangeRequest = {
383	        walletId: this.id,
384	        version,
385	        nonce,
386	        deadline,
387	        newOwners,
388	        newConfirmations,
389	      };
390	      digest = hashPolicyChange(req);
391	      payload = { kind: 'policy-change', deadline, version, newOwners, newConfirmations };
392	    }
393	
394	    // (4) 阈值签名：恢复 → 去重 → 必须为当前所有者 → 数量达到当前确认数
395	    this.verifyThresholdSignatures(digest, signatures, Invalid);
396	
397	    // (5) 原子生效（到队列为止）：入队 + 消费 nonce。
398	    //     入队失败（同一摘要重复等）时不消费 nonce。
399	    let task: WalletTask;
400	    try {
401	      task = this.queue.enqueue({
402	        nonce,
403	        digest: digest.toString('hex'),
404	        payload,
405	        submittedAt: this.now(),
406	      });
407	    } catch (err) {
408	      if (err instanceof InvalidQueueStateError) throw new Invalid(err.message);
409	      throw err;
410	    }
411	    this.usedNonces.add(nonce);
412	    this.nextNonce = nonce + 1n;
413	    return task;
414	  }
415	
416	  /** 按“当前策略”的所有者集合与确认数校验签名收集 */
417	  private verifyThresholdSignatures(
418	    digest: Uint8Array,
419	    signatures: readonly Uint8Array[],
420	    Invalid: new (msg: string) => Error,
421	  ): void {
422	    if (!Array.isArray(signatures)) {
423	      throw new Invalid('signatures must be an array');
424	    }
425	    if (signatures.length === 0) throw new Invalid('missing signatures');
426	
427	    const signedBy = new Set<Address>();
428	    for (const sig of signatures) {
429	      if (!(sig instanceof Uint8Array) || sig.length !== 65) {
430	        throw new Invalid('each signature must be a 65-byte r||s||v blob');
431	      }
432	      const signer = recoverAddress(digest, Uint8Array.from(sig));
433	      if (signer === null) throw new Invalid('malformed or non-canonical signature');
434	      if (!this.ownerSet.has(signer)) {
435	        // 非所有者签名：既可能是伪造，也可能是签名载荷与提交内容不匹配
436	        throw new Invalid('signature does not match payload or signer is not an owner');
437	      }
438	      signedBy.add(signer); // 地址去重：同一所有者多签只计一次
439	    }
440	    if (BigInt(signedBy.size) < this.confirmations) {
441	      throw new Invalid(
442	        `threshold not met: need ${this.confirmations} distinct owners, got ${signedBy.size}`,
443	      );
444	    }
445	  }
446	
447	  /** 队列执行器回调：定义两类任务的生效语义 */
448	  private applyTask(task: WalletTask): unknown {
449	    const p = task.payload;
450	    if (p.kind === 'transaction') {
451	      // 普通交易既有执行结果：一个可观察的执行产物；不触碰策略状态。
452	      // 截止时间只在提交阶段核对（RequestExpired），不作为执行闸门，以保持既有执行结果不变。
453	      return {
454	        kind: 'transfer',
455	        to: p.to,
456	        value: p.value,
457	        data: Buffer.from(p.data).toString('hex'),
458	      };
459	    }
460	
461	    // 策略变更：仅当绑定版本仍等于当前版本时生效
462	    if (p.version !== this.version) {
463	      throw new PolicyConflict(
464	        `policy version drifted: task bound ${p.version}, current ${this.version}`,
465	      );
466	    }
467	    // 所有者集合与确认数同时替换；版本恰好递增一次
468	    this.owners = [...p.newOwners];
469	    this.ownerSet.clear();
470	    for (const o of this.owners) this.ownerSet.add(o);
471	    this.confirmations = p.newConfirmations;
472	    this.version += 1n;
473	    return {
474	      kind: 'policy-applied',
475	      version: this.version,
476	      owners: [...this.owners],
477	      confirmations: this.confirmations,
478	    };
479	  }
480	}
481	
482	// ---------- 所有者列表规范化（空/重复/零地址校验） ----------
483	
484	function normalizeOwnerList(
485	  input: readonly string[],
486	  ErrorCtor: typeof InvalidPolicyChange | typeof InvalidTransaction = InvalidPolicyChange,
487	): Address[] {
488	  if (!Array.isArray(input) || input.length === 0) {
489	    throw new ErrorCtor('owners list must be a non-empty array');
490	  }
491	  const out: Address[] = [];
492	  const seen = new Set<Address>();
493	  for (const raw of input) {
494	    const addr = normalizeAddress(raw);
495	    if (addr === null) throw new ErrorCtor(`invalid owner address: ${String(raw)}`);
496	    if (addr === ZERO_ADDRESS || isZeroAddress(addr)) {
497	      throw new ErrorCtor('zero address is not allowed as owner');
498	    }
499	    if (seen.has(addr)) throw new ErrorCtor(`duplicate owner: ${addr}`);
500	    seen.add(addr);
501	    out.push(addr);
502	  }
503	  return out;
504	}
