1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { MultiSigWallet } from '../src/wallet.ts';
4	import { PolicyConflict, RequestExpired, TaskNotFoundError, InvalidQueueStateError } from '../src/errors.ts';
5	import { actors, addresses, fakeClock, signPolicyChange, signTransaction } from './helpers.ts';
6	
7	const WALLET = 'wallet-exec';
8	
9	function setup(ownerCount = 3, confirmations = 2n) {
10	  const ownerActors = actors(ownerCount);
11	  const clock = fakeClock(1000n);
12	  const wallet = new MultiSigWallet({
13	    id: WALLET,
14	    owners: addresses(ownerActors),
15	    confirmations,
16	    now: clock.now,
17	  });
18	  return { ownerActors, clock, wallet };
19	}
20	
21	function propose(wallet: MultiSigWallet, ownerActors: ReturnType<typeof actors>, opts: {
22	  nonce: bigint;
23	  version?: bigint;
24	  deadline?: bigint;
25	  newOwners: string[];
26	  newConfirmations: bigint;
27	}) {
28	  const version = opts.version ?? 1n;
29	  const deadline = opts.deadline ?? 5000n;
30	  const sigs = signPolicyChange(ownerActors.slice(0, Number(2)), {
31	    walletId: WALLET,
32	    version,
33	    nonce: opts.nonce,
34	    deadline,
35	    newOwners: opts.newOwners,
36	    newConfirmations: opts.newConfirmations,
37	  });
38	  return wallet.proposePolicyChange(
39	    { version, nonce: opts.nonce, deadline, newOwners: opts.newOwners, newConfirmations: opts.newConfirmations },
40	    sigs,
41	  );
42	}
43	
44	test('策略变更执行成功：所有者与确认数同时替换，版本恰好递增一次', () => {
45	  const { wallet, ownerActors } = setup();
46	  const newbie = actors(1)[0]!;
47	  const newOwners = [ownerActors[0]!.address, newbie.address];
48	
49	  const task = propose(wallet, ownerActors, { nonce: 0n, newOwners, newConfirmations: 1n });
50	  const done = wallet.executeTask(task.id);
51	
52	  assert.equal(done.status, 'executed');
53	  assert.deepEqual(done.receipt!.failureReason, null);
54	  assert.equal(wallet.policyVersion, 2n);
55	  assert.deepEqual(wallet.currentOwners, newOwners);
56	  assert.equal(wallet.requiredConfirmations, 1n);
57	  // 旧所有者退出、新所有者生效
58	  assert.equal(wallet.isOwner(ownerActors[1]!.address), false);
59	  assert.equal(wallet.isOwner(newbie.address), true);
60	});
61	
62	test('原子替换：newOwners 与 newConfirmations 来自同一提案，无中间态可读', () => {
63	  const { wallet, ownerActors } = setup();
64	  const newbie = actors(1)[0]!;
65	  const newOwners = [ownerActors[2]!.address, newbie.address];
66	  const task = propose(wallet, ownerActors, { nonce: 0n, newOwners, newConfirmations: 2n });
67	  // 执行前仍是旧策略
68	  assert.equal(wallet.requiredConfirmations, 2n);
69	  assert.equal(wallet.isOwner(newbie.address), false);
70	  wallet.executeTask(task.id);
71	  assert.deepEqual(wallet.currentOwners, newOwners);
72	  assert.equal(wallet.requiredConfirmations, 2n);
73	});
74	
75	test('成功后进入既有执行终态：重复执行幂等，不再改变策略/版本', () => {
76	  const { wallet, ownerActors } = setup();
77	  const newbie = actors(1)[0]!;
78	  const newOwners = [ownerActors[0]!.address, newbie.address];
79	  const task = propose(wallet, ownerActors, { nonce: 0n, newOwners, newConfirmations: 1n });
80	  wallet.executeTask(task.id);
81	  const again = wallet.executeTask(task.id);
82	  assert.equal(again.status, 'executed');
83	  assert.equal(wallet.policyVersion, 2n, '版本不得再次递增');
84	});
85	
86	test('版本漂移：先执行另一个策略变更，旧任务执行 → PolicyConflict 失败终态，策略不变', () => {
87	  const { wallet, ownerActors } = setup(3, 2n);
88	
89	  // 提案 A（排在队首）：把阈值降为 1，所有者换成 [o0, newbie]
90	  const newbie = actors(1)[0]!;
91	  const ownersA = [ownerActors[0]!.address, newbie.address];
92	  const taskA = propose(wallet, ownerActors, { nonce: 0n, newOwners: ownersA, newConfirmations: 1n });
93	
94	  // 人为构造“绑定旧版本但排在 A 之后”的任务 B：
95	  // A 先执行后版本变为 2；B 仍绑定 version=1。
96	  // 用当前所有者为 B 收集签名（提交时版本仍为 1，合法）。
97	  const ownersB = [ownerActors[0]!.address, ownerActors[2]!.address];
98	  const sigsB = signPolicyChange(ownerActors.slice(0, 2), {
99	    walletId: WALLET,
100	    version: 1n,
101	    nonce: 1n,
102	    deadline: 6000n,
103	    newOwners: ownersB,
104	    newConfirmations: 2n,
105	  });
