116	  const resultB = wallet.executeTask(taskB.id);
117	  assert.equal(resultB.status, 'failed');
118	  assert.equal(resultB.receipt!.failureReason, 'PolicyConflict');
119	  // 策略保持 A 的结果，不被 B 改动，版本不再递增
120	  assert.equal(wallet.policyVersion, 2n);
121	  assert.deepEqual(wallet.currentOwners, ownersA);
122	  assert.equal(wallet.requiredConfirmations, 1n);
123	
124	  // 失败终态幂等：再次执行不重放
125	  const again = wallet.executeTask(taskB.id);
126	  assert.equal(again, resultB);
127	  assert.equal(wallet.policyVersion, 2n);
128	});
