130	test('PolicyConflict 任务仍占用其 nonce（不回滚 nonce 消费），队列继续向后推进', () => {
131	  const { wallet, ownerActors } = setup(3, 2n);
132	  const newbie = actors(1)[0]!;
133	  const ownersA = [ownerActors[0]!.address, newbie.address];
134	  const taskA = propose(wallet, ownerActors, { nonce: 0n, newOwners: ownersA, newConfirmations: 1n });
