  walletId: string;
  taskDigest: string;
  nonce: bigint | number;
  deadline: bigint | number;
}): Buffer {
  return digest(TAG_CANCEL, [
    encBytes(walletIdBytes(req.walletId)),
    encBytes(hexToBytes(req.taskDigest)),
    encUint(req.nonce),
    encUint(deadlineToBigint(req.deadline)),
  ]);
}

